create or replace function public.sellertray_report_summary(p_tenant_id uuid,p_days integer default 30)
returns jsonb language plpgsql security definer set search_path=''
as $$declare v_user_id uuid:=auth.uid();v_days integer:=greatest(1,least(coalesce(p_days,30),365));v_since timestamptz;v_result jsonb;begin
if v_user_id is null then raise exception 'SellerTray authentication required' using errcode='42501';end if;if not public.sellertray_user_has_capability(p_tenant_id,v_user_id,'can_view_reports') then raise exception 'You do not have permission to view business reports' using errcode='42501';end if;v_since:=now()-make_interval(days=>v_days);
with eligible as(select o.* from public.orders o where o.tenant_id=p_tenant_id and o.deleted_at is null and o.status<>'draft' and o.created_at>=v_since and public.sellertray_user_can_read_report_branch(p_tenant_id,o.branch_id,v_user_id)),order_stats as(select count(*)::int orders,count(*)filter(where status='completed')::int completed,count(*)filter(where status in('rejected','cancelled'))::int unsuccessful,count(*)filter(where source='whatsapp')::int whatsapp_orders,count(*)filter(where source='manual')::int manual_orders,count(*)filter(where payment_status='paid')::int paid_orders,count(*)filter(where payment_status in('unpaid','pending','verification_required','payment_issue') and status not in('rejected','cancelled'))::int awaiting_payment,coalesce(sum(total_amount)filter(where status='completed'),0)::numeric order_value,coalesce(sum(amount_paid)filter(where status='completed'),0)::numeric paid_value,count(*)filter(where fulfillment_status='out_for_delivery')::int out_for_delivery,count(*)filter(where fulfillment_status='delivered')::int delivered,count(*)filter(where fulfillment_status='collected')::int collected,count(*)filter(where status='ready' and fulfillment_status='unassigned')::int awaiting_fulfillment from eligible),payment_method_stats as(select op.method_type,count(*)::int method_count from public.order_payments op join eligible o on o.id=op.order_id and o.tenant_id=op.tenant_id group by op.method_type),payment_stats as(select count(*)filter(where op.status='pending_verification')::int verification_required,count(*)filter(where op.status='failed')::int failed,count(*)filter(where op.exception_state<>'none')::int exceptions from public.order_payments op join eligible o on o.id=op.order_id and o.tenant_id=op.tenant_id),method_json as(select coalesce(jsonb_object_agg(method_type,method_count),'{}'::jsonb) methods from payment_method_stats),top_items as(select coalesce(jsonb_agg(jsonb_build_object('name',x.item_name,'quantity',x.quantity,'value',x.value) order by x.value desc,x.quantity desc),'[]'::jsonb) items from(select oi.item_name,sum(oi.quantity)::numeric quantity,sum(oi.quantity*coalesce(oi.unit_price,0))::numeric value from public.order_items oi join eligible o on o.id=oi.order_id and o.tenant_id=oi.tenant_id where o.status='completed' group by oi.item_name order by value desc,quantity desc limit 10)x) select jsonb_build_object('days',v_days,'orders',jsonb_build_object('total',os.orders,'completed',os.completed,'unsuccessful',os.unsuccessful,'whatsapp',os.whatsapp_orders,'manual',os.manual_orders,'orderValue',os.order_value,'averageOrderValue',case when os.completed>0 then os.order_value/os.completed else 0 end),'payments',jsonb_build_object('paidOrders',os.paid_orders,'awaitingPayment',os.awaiting_payment,'paidValue',os.paid_value,'verificationRequired',ps.verification_required,'failed',ps.failed,'exceptions',ps.exceptions,'methods',mj.methods),'fulfillment',jsonb_build_object('outForDelivery',os.out_for_delivery,'delivered',os.delivered,'collected',os.collected,'awaitingFulfillment',os.awaiting_fulfillment),'topItems',ti.items) into v_result from order_stats os,payment_stats ps,method_json mj,top_items ti;return v_result;end$$;
revoke all on function public.sellertray_report_summary(uuid,integer) from public,anon;grant execute on function public.sellertray_report_summary(uuid,integer) to authenticated,service_role;

create or replace function public.sellertray_report_center_v2(p_tenant_id uuid,p_days integer default 30)
returns jsonb language plpgsql security definer set search_path=''
as $$declare v_user_id uuid:=auth.uid();v_days integer:=greatest(1,least(coalesce(p_days,30),365));v_since timestamptz;v_base jsonb;v_branches jsonb;v_trend jsonb;v_channels jsonb;v_customers jsonb;begin
if v_user_id is null then raise exception 'SellerTray authentication required' using errcode='42501';end if;if not public.sellertray_user_has_capability(p_tenant_id,v_user_id,'can_view_reports') then raise exception 'You do not have permission to view business reports' using errcode='42501';end if;v_since:=now()-make_interval(days=>v_days);v_base:=public.sellertray_report_center(p_tenant_id,v_days);
select coalesce(jsonb_agg(jsonb_build_object('branchId',x.branch_id,'branchCode',x.branch_code,'branchName',x.branch_name,'isActive',x.is_active,'orders',x.orders,'completed',x.completed,'orderValue',x.order_value,'paidValue',x.paid_value,'whatsappOrders',x.whatsapp_orders,'closedShifts',x.closed_shifts,'cashVariance',x.cash_variance)order by x.order_value desc,x.orders desc,x.branch_name),'[]'::jsonb)into v_branches from(select b.id branch_id,b.code branch_code,b.name branch_name,b.is_active,count(o.id)::int orders,count(o.id)::int completed,coalesce(sum(o.total_amount),0)::numeric order_value,coalesce(sum(o.amount_paid),0)::numeric paid_value,count(o.id)filter(where o.source='whatsapp')::int whatsapp_orders,coalesce(s.closed_shifts,0)::int closed_shifts,coalesce(s.cash_variance,0)::numeric cash_variance from public.branches b left join public.orders o on o.tenant_id=b.tenant_id and o.branch_id=b.id and o.deleted_at is null and o.status='completed' and o.created_at>=v_since left join(select cs.branch_id,count(*)filter(where cs.status in('closed','reviewed'))::int closed_shifts,coalesce(sum(cs.variance)filter(where cs.status in('closed','reviewed')),0)::numeric cash_variance from public.sellertray_cash_shifts cs where cs.tenant_id=p_tenant_id and cs.opened_at>=v_since and public.sellertray_user_can_read_report_branch(p_tenant_id,cs.branch_id,v_user_id)group by cs.branch_id)s on s.branch_id=b.id where b.tenant_id=p_tenant_id and public.sellertray_user_can_read_report_branch(p_tenant_id,b.id,v_user_id)group by b.id,b.code,b.name,b.is_active,s.closed_shifts,s.cash_variance)x;
select coalesce(jsonb_agg(jsonb_build_object('date',x.business_date,'orders',x.orders,'orderValue',x.order_value,'paidValue',x.paid_value)order by x.business_date),'[]'::jsonb)into v_trend from(select(o.created_at at time zone 'UTC')::date business_date,count(*)::int orders,coalesce(sum(o.total_amount),0)::numeric order_value,coalesce(sum(o.amount_paid),0)::numeric paid_value from public.orders o where o.tenant_id=p_tenant_id and o.deleted_at is null and o.status='completed' and o.created_at>=v_since and public.sellertray_user_can_read_report_branch(p_tenant_id,o.branch_id,v_user_id)group by(o.created_at at time zone 'UTC')::date)x;
select coalesce(jsonb_agg(jsonb_build_object('channel',x.source,'orders',x.orders,'orderValue',x.order_value,'paidValue',x.paid_value)order by x.order_value desc,x.orders desc,x.source),'[]'::jsonb)into v_channels from(select o.source,count(*)::int orders,coalesce(sum(o.total_amount),0)::numeric order_value,coalesce(sum(o.amount_paid),0)::numeric paid_value from public.orders o where o.tenant_id=p_tenant_id and o.deleted_at is null and o.status='completed' and o.created_at>=v_since and public.sellertray_user_can_read_report_branch(p_tenant_id,o.branch_id,v_user_id)group by o.source)x;
select coalesce(jsonb_agg(jsonb_build_object('customerId',x.customer_id,'customerName',x.customer_name,'orders',x.orders,'orderValue',x.order_value,'paidValue',x.paid_value,'lastOrderAt',x.last_order_at)order by x.order_value desc,x.orders desc,x.last_order_at desc),'[]'::jsonb)into v_customers from(select o.customer_id,coalesce(c.display_name,c.phone,c.wa_id,'Walk-in customer')customer_name,count(*)::int orders,coalesce(sum(o.total_amount),0)::numeric order_value,coalesce(sum(o.amount_paid),0)::numeric paid_value,max(o.created_at)last_order_at from public.orders o left join public.customers c on c.tenant_id=o.tenant_id and c.id=o.customer_id where o.tenant_id=p_tenant_id and o.deleted_at is null and o.status='completed' and o.created_at>=v_since and public.sellertray_user_can_read_report_branch(p_tenant_id,o.branch_id,v_user_id)group by o.customer_id,coalesce(c.display_name,c.phone,c.wa_id,'Walk-in customer')order by order_value desc,orders desc,last_order_at desc limit 10)x;
return v_base||jsonb_build_object('summary',public.sellertray_report_summary(p_tenant_id,v_days),'branchPerformance',v_branches,'salesTrend',v_trend,'channels',v_channels,'topCustomers',v_customers);end$$;
revoke all on function public.sellertray_report_center_v2(uuid,integer) from public,anon;grant execute on function public.sellertray_report_center_v2(uuid,integer) to authenticated,service_role;
